import type { DocumentContent } from "../documents";

const content = {
    html: resolveAssets("<h1 id=\"comparison\">Comparison</h1><p>It&#39;s generally helpful to learn a new thing in contrast to things we already know, and in that spirit we have compiled a short comparison overview of what Destack looks like coming from each of these languages.\nThe Destack language is deliberately trying to be &quot;TypeScript++&quot;, so that&#39;s where we begin, but there are many similarities and some differences to other well known languages - most notably Rust - that bear pointing out.</p>\n<h2 id=\"typescript\">TypeScript</h2><p><strong>Destack is a superset of the &quot;modern strict&quot; subset of TypeScript</strong>.\nThe intended use case for Destack is making TS-shaped code correct and optimal, which requires both cutting all accumulated dynamic magic and introducing systems-y features for memory control.\nAccordingly, Destack excludes legacy syntax and all sorts of dynamic shapes and protocols that are not statically sound, and also removes a few rarely used footguns.</p>\n<p>It&#39;s important to note that Destack deliberately has <strong>no JavaScript or NPM interoperability</strong>: <code>.ds</code> code cannot import or call arbitrary JS, and Destack packages cannot depend on npm packages in any way.\nThe main reason for this is that to take full advantage of Destack&#39;s features and full integration across the stack, we need to essentially rewrite all libraries anyway.</p>\n<p>In general, most strict modern TypeScript needs no changes at all:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">TypeScript</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">interface</span> <span data-k=\"type\">User</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"property\">name</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"property\">age</span><span data-k=\"punct\">:</span> <span data-k=\"type\">number</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">adults</span><span data-k=\"punct\">(</span><span data-k=\"name\">users</span><span data-k=\"punct\">:</span> <span data-k=\"type\">User</span><span data-k=\"punct\">[</span><span data-k=\"punct\">]</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">User</span><span data-k=\"punct\">[</span><span data-k=\"punct\">]</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">return</span> <span data-k=\"name\">users</span><span data-k=\"punct\">.</span><span data-k=\"property\">filter</span><span data-k=\"punct\">(</span><span data-k=\"punct\">(</span><span data-k=\"name\">user</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"name\">user</span><span data-k=\"punct\">.</span><span data-k=\"property\">age</span> <span data-k=\"punct\">&gt;=</span> <span data-k=\"literal\">18</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">names</span> <span data-k=\"punct\">=</span> <span data-k=\"function\">adults</span><span data-k=\"punct\">(</span><span data-k=\"punct\">[</span><span data-k=\"punct\">{</span> <span data-k=\"property\">name</span><span data-k=\"punct\">:</span> <span data-k=\"string\">&quot;Ada&quot;</span><span data-k=\"punct\">,</span> <span data-k=\"property\">age</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">36</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">]</span><span data-k=\"punct\">)</span><span data-k=\"punct\">.</span><span data-k=\"property\">map</span><span data-k=\"punct\">(</span><span data-k=\"punct\">(</span><span data-k=\"name\">user</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"name\">user</span><span data-k=\"punct\">.</span><span data-k=\"property\">name</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><h3 id=\"modules\">Modules</h3><p>Destack supports only ESM syntax: one static module graph, nothing mutable at runtime.</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Feature</th>\n<th>Example</th>\n<th>Ruling</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>Type-qualified imports / exports</strong></td>\n<td><code>import type { User } from &quot;./user&quot;</code></td>\n<td>not supported, plain imports and exports preserve the declaration&#39;s symbol space</td>\n</tr>\n<tr>\n<td><strong>CommonJS</strong></td>\n<td><code>require(&quot;x&quot;)</code>, <code>module.exports</code></td>\n<td>not supported, a legacy mutable runtime module system</td>\n</tr>\n<tr>\n<td><strong>Namespace declarations</strong></td>\n<td><code>namespace Name { ... }</code></td>\n<td>not supported, use real modules</td>\n</tr>\n<tr>\n<td><strong>String module declarations</strong></td>\n<td><code>declare module &quot;pkg&quot; { ... }</code></td>\n<td>not supported, declare real modules instead</td>\n</tr>\n<tr>\n<td><strong>Declaration merging</strong></td>\n<td>two <code>interface User</code> blocks</td>\n<td>not supported, one declaration per name, extensions cover augmentation</td>\n</tr>\n<tr>\n<td><strong>Import type queries</strong></td>\n<td><code>import(&quot;pkg&quot;).User</code></td>\n<td>not supported, use ordinary static imports</td>\n</tr>\n<tr>\n<td><strong>Dynamic module loading</strong></td>\n<td><code>import(expr)</code></td>\n<td>not source-level loading, though JS output may still chunk</td>\n</tr>\n<tr>\n<td><strong>Import defer</strong></td>\n<td><code>import defer * as ns from &quot;pkg&quot;</code></td>\n<td>not supported</td>\n</tr>\n<tr>\n<td><strong>Import assertions</strong></td>\n<td><code>assert { type: &quot;json&quot; }</code></td>\n<td>not supported, use standardized <code>with { ... }</code> attributes</td>\n</tr>\n<tr>\n<td><strong>String export names</strong></td>\n<td><code>export { value as &quot;name&quot; }</code></td>\n<td>not supported</td>\n</tr>\n<tr>\n<td><strong>Circular inference</strong></td>\n<td>mutually inferred module exports</td>\n<td>not supported across modules</td>\n</tr>\n<tr>\n<td><strong>Flow and JSDoc typing</strong></td>\n<td><code>/** @type {Foo} */</code></td>\n<td>ignored, or rejected when not valid TS/TS++</td>\n</tr>\n</tbody></table></div><h3 id=\"values\">Values</h3><p>Bindings are strict-mode <code>const</code> and <code>let</code> with definite assignment, and the legacy spellings are gone.</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Feature</th>\n<th>Example</th>\n<th>Ruling</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>Var declarations</strong></td>\n<td><code>var x</code></td>\n<td>not supported, <code>var</code> scoping is unnecessary with <code>const</code> and <code>let</code></td>\n</tr>\n<tr>\n<td><strong>Destructuring</strong></td>\n<td><code>const { name } = user</code></td>\n<td>supported in declarations, assignments, parameters, catch bindings, and loops</td>\n</tr>\n<tr>\n<td><strong>Shadowable <code>undefined</code></strong></td>\n<td><code>let undefined = value</code></td>\n<td>not supported, <code>undefined</code> is a literal keyword just like <code>null</code></td>\n</tr>\n<tr>\n<td><strong>Sequence expressions</strong></td>\n<td><code>(a, b, c)</code></td>\n<td>not supported, parenthesized comma lists are explicit tuples in <code>.ds</code></td>\n</tr>\n<tr>\n<td><strong>Array-form tuple types</strong></td>\n<td><code>[string, number]</code></td>\n<td>supported and preserved as the TypeScript-compatible spelling of a tuple type</td>\n</tr>\n<tr>\n<td><strong>Definite assignment assertions</strong></td>\n<td><code>let x!: T</code>, <code>field!: T</code></td>\n<td>rejected in <code>.ds</code>, locals and fields must be initialized before use</td>\n</tr>\n<tr>\n<td><strong>Sloppy mode</strong></td>\n<td>duplicate declarations, <code>with</code></td>\n<td>not supported, Destack targets strict mode</td>\n</tr>\n<tr>\n<td><strong>Callable <code>Symbol</code></strong></td>\n<td><code>Symbol(&quot;name&quot;)</code></td>\n<td>not supported, use <code>Symbol.create(&quot;name&quot;)</code></td>\n</tr>\n</tbody></table></div><h3 id=\"primitives\">Primitives</h3><p>The TypeScript primitives keep their meaning, but we support more scalar types.</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Feature</th>\n<th>Example</th>\n<th>Ruling</th>\n</tr>\n</thead><tbody><tr>\n<td><strong><code>number</code></strong></td>\n<td><code>let x: number</code></td>\n<td>stays the default numeric type, an alias for <code>float64</code></td>\n</tr>\n<tr>\n<td><strong>Integer and float widths</strong></td>\n<td><code>int32</code>, <code>uint8</code>, <code>float32</code>, ...</td>\n<td>added as real scalar types</td>\n</tr>\n<tr>\n<td><strong>Single-quoted literals</strong></td>\n<td><code>&#39;A&#39;</code></td>\n<td><code>char</code> in <code>.ds</code>, string in <code>.ts</code> / <code>.tsx</code></td>\n</tr>\n<tr>\n<td><strong>String indexing</strong></td>\n<td><code>text[0]</code></td>\n<td>yields <code>char</code> in <code>.ds</code>, and traps on a lone surrogate</td>\n</tr>\n<tr>\n<td><strong><code>symbol</code></strong></td>\n<td><code>let key: symbol</code></td>\n<td>supported as a regular property key type</td>\n</tr>\n<tr>\n<td><strong><code>unique symbol</code></strong></td>\n<td><code>const key: unique symbol</code></td>\n<td>supported for statically known singleton keys</td>\n</tr>\n</tbody></table></div><h4 id=\"characters\">Characters</h4><p>Single quotes are scalars, double quotes are strings:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Characters</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">initial</span> <span data-k=\"punct\">=</span> <span data-k=\"string\">'A'</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// char, not a one-character string</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">text</span> <span data-k=\"punct\">=</span> <span data-k=\"string\">&quot;héllo&quot;;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"name\">text</span><span data-k=\"punct\">.</span><span data-k=\"property\">length</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">uint</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// UTF-16 code units, as in JS</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"name\">text</span><span data-k=\"punct\">[</span><span data-k=\"literal\">1</span><span data-k=\"punct\">]</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">char</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><h3 id=\"arithmetic\">Arithmetic</h3><p>Integer arithmetic traps on overflow in all build configurations, and <code>as</code> never loses information.</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Feature</th>\n<th>Example</th>\n<th>Ruling</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>Overflow</strong></td>\n<td><code>int32</code> max <code>+ 1</code></td>\n<td>traps in every build mode</td>\n</tr>\n<tr>\n<td><strong>Wrapping</strong></td>\n<td><code>(a + b) &amp; 0xff</code> idioms</td>\n<td>explicit: <code>wrappingAdd</code>, <code>Wrapping&lt;T&gt;</code></td>\n</tr>\n<tr>\n<td><strong>Numeric <code>as</code></strong></td>\n<td><code>big as int8</code></td>\n<td>lossless conversions only, lossy ones are explicit methods</td>\n</tr>\n</tbody></table></div><h4 id=\"conversions\">Conversions</h4><p>Lossy numeric conversion requires an explicit method call:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Conversions</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">big</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">100_000</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">bad</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">big</span> <span data-k=\"keyword\">as</span> <span data-k=\"type\">int8</span><span data-k=\"punct\">;</span>    <span data-k=\"comment\">// ERROR: lossy conversion</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"name\">big</span><span data-k=\"punct\">.</span><span data-k=\"property\">truncate</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">int8</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>       <span data-k=\"comment\">// keep the low bits</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"name\">big</span><span data-k=\"punct\">.</span><span data-k=\"property\">saturate</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">int8</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>       <span data-k=\"comment\">// clamp to bounds</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"name\">big</span><span data-k=\"punct\">.</span><span data-k=\"property\">tryInto</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">int8</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>        <span data-k=\"comment\">// checked</span></span></span></code></pre></figure><h3 id=\"unknown\">Unknown</h3><p><code>unknown</code> stays; <code>any</code> dies.</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Feature</th>\n<th>Example</th>\n<th>Ruling</th>\n</tr>\n</thead><tbody><tr>\n<td><strong><code>any</code></strong></td>\n<td><code>let x: any</code></td>\n<td>forbidden in all sources, an unchecked escape hatch in both directions</td>\n</tr>\n<tr>\n<td><strong><code>unknown</code></strong></td>\n<td><code>declare const data: unknown</code></td>\n<td>supported, and represented as <code>Dynamic&lt;unknown&gt;</code> in value positions</td>\n</tr>\n</tbody></table></div><h4 id=\"any-and-unknown\">Any and Unknown</h4><p><code>unknown</code> does the safe half of <code>any</code>&#39;s job:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Any and Unknown</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">const</span> <span data-k=\"name\">input</span><span data-k=\"punct\">:</span> <span data-k=\"type\">any</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// ERROR: `any` is forbidden</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">const</span> <span data-k=\"name\">data</span><span data-k=\"punct\">:</span> <span data-k=\"type\">unknown</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">if</span> <span data-k=\"punct\">(</span><span data-k=\"name\">data</span> is <span data-k=\"name\">string</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\">    <span data-k=\"name\">data</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><h3 id=\"shapes\">Shapes</h3><p>Object shapes are static and exact: no prototype tricks, no runtime mutation, and fresh literals are checked everywhere.</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Feature</th>\n<th>Example</th>\n<th>Ruling</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>Interchangeable <code>type</code> / <code>interface</code></strong></td>\n<td>data-shaped <code>interface Point</code> in a field</td>\n<td>diverges in storage positions</td>\n</tr>\n<tr>\n<td><strong><code>Record&lt;K, V&gt;</code></strong></td>\n<td><code>Record&lt;string, User&gt;</code></td>\n<td>mapped utility type, use <code>Map&lt;K, V&gt;</code> for dynamic keyed storage</td>\n</tr>\n<tr>\n<td><strong><code>object</code></strong></td>\n<td><code>let value: object</code></td>\n<td>not supported, use a structural shape, <code>unknown</code>, or an  interface</td>\n</tr>\n<tr>\n<td><strong>Declaration expressions</strong></td>\n<td><code>const C = class {}</code></td>\n<td>not supported, runtime type generation is not statically knowable</td>\n</tr>\n<tr>\n<td><strong>Prototype objects</strong></td>\n<td><code>.prototype</code>, <code>.__proto__</code>, <code>Object.setPrototypeOf</code></td>\n<td>not supported</td>\n</tr>\n<tr>\n<td><strong>Shape mutation</strong></td>\n<td><code>delete obj.x</code>, <code>Object.defineProperty</code></td>\n<td>forbidden, object shapes must stay statically known</td>\n</tr>\n<tr>\n<td><strong>Metaobject dispatch</strong></td>\n<td><code>Proxy</code>, most <code>Reflect.*</code> APIs</td>\n<td>not supported</td>\n</tr>\n<tr>\n<td><strong>Array holes</strong></td>\n<td><code>[1,,3]</code></td>\n<td>not supported, sequences are dense</td>\n</tr>\n<tr>\n<td><strong>Excess properties</strong></td>\n<td>fresh literal with extra fields</td>\n<td>rejected at every boundary, not just some</td>\n</tr>\n</tbody></table></div><h4 id=\"type-vs-interface\">Type vs Interface</h4><p>In TypeScript, <code>type</code> and <code>interface</code> are mostly interchangeable.\nIn Destack, they diverge in storage positions: closed aliases are exact data shapes, while interfaces are constraints and erase to <code>Dynamic&lt;T&gt;</code> when stored.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Type vs Interface</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">type</span> <span data-k=\"type\">Point</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">{</span> <span data-k=\"property\">x</span><span data-k=\"punct\">:</span> <span data-k=\"type\">number</span><span data-k=\"punct\">;</span> <span data-k=\"property\">y</span><span data-k=\"punct\">:</span> <span data-k=\"type\">number</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">struct</span> <span data-k=\"type\">Rectangle</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">    <span data-k=\"property\">start</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Point</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// exact storage, as in TypeScript</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">interface</span> <span data-k=\"type\">PointLike</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\">    <span data-k=\"property\">x</span><span data-k=\"punct\">:</span> <span data-k=\"type\">number</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\">    <span data-k=\"property\">y</span><span data-k=\"punct\">:</span> <span data-k=\"type\">number</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">12</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">struct</span> <span data-k=\"type\">Sprite</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">13</span><span class=\"markdown-code-text\">    <span data-k=\"property\">position</span><span data-k=\"punct\">:</span> <span data-k=\"type\">PointLike</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// erased storage: Dynamic&lt;PointLike&gt;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">14</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><h4 id=\"freshness\">Freshness</h4><p>The classic typo stays caught, at every boundary:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Freshness</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">interface</span> <span data-k=\"type\">SquareConfig</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"property\">color</span><span data-k=\"punct\">?</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"property\">width</span><span data-k=\"punct\">?</span><span data-k=\"punct\">:</span> <span data-k=\"type\">number</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">createSquare</span><span data-k=\"punct\">(</span><span data-k=\"name\">config</span><span data-k=\"punct\">:</span> <span data-k=\"type\">SquareConfig</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">void</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"><span data-k=\"function\">createSquare</span><span data-k=\"punct\">(</span><span data-k=\"punct\">{</span> <span data-k=\"property\">colour</span><span data-k=\"punct\">:</span> <span data-k=\"string\">&quot;red&quot;</span><span data-k=\"punct\">,</span> <span data-k=\"property\">width</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">100</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// ERROR: excess property `colour`</span></span></span></code></pre></figure><h3 id=\"classes\">Classes</h3><p>Classes keep their TypeScript surface but become properly nominal.</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Feature</th>\n<th>Example</th>\n<th>Ruling</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>Structural classes</strong></td>\n<td>same-shaped classes interchangeable</td>\n<td>classes are nominal, structure does not substitute for declarations</td>\n</tr>\n<tr>\n<td><strong>Private fields</strong></td>\n<td><code>#field</code></td>\n<td>not supported, redundant with real <code>private</code> in <code>.ds</code></td>\n</tr>\n<tr>\n<td><strong>Parameter properties</strong></td>\n<td><code>constructor(private name: string)</code></td>\n<td>not supported, declare fields and assignments explicitly</td>\n</tr>\n<tr>\n<td><strong>Class index signatures</strong></td>\n<td><code>class C { [key: string]: T }</code></td>\n<td>not supported, classes have fixed declared members</td>\n</tr>\n</tbody></table></div><h4 id=\"nominality\">Nominality</h4><p>Two classes with the same shape are still two classes:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Nominality</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">class</span> <span data-k=\"type\">Point2</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"property\">x</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">0</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"property\">y</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">0</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">class</span> <span data-k=\"type\">Point3</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\">    <span data-k=\"property\">x</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">0</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\">    <span data-k=\"property\">y</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">0</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\">    <span data-k=\"property\">z</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">0</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">12</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">point</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Point2</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span> <span data-k=\"type\">Point3</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// ERROR (OK in TypeScript)</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">13</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">plain</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Point2</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">{</span> <span data-k=\"property\">x</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">0</span><span data-k=\"punct\">,</span> <span data-k=\"property\">y</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">0</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// ERROR (also OK in TypeScript!)</span></span></span></code></pre></figure><p>TypeScript classes only turn nominal once they have a <code>private</code> member, which is why the branding hack works; Destack classes are nominal always.</p>\n<h3 id=\"enums\">Enums</h3><p>Enum fields are nominal constants, without TypeScript&#39;s number leakage.</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Feature</th>\n<th>Example</th>\n<th>Ruling</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>Enum coercion</strong></td>\n<td><code>Level.A</code> as <code>number</code></td>\n<td>no implicit coercion, enum fields are nominal constants</td>\n</tr>\n</tbody></table></div><h3 id=\"generics\">Generics</h3><p>Generics work as in TypeScript, with explicitness required where inference would have to guess.</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Feature</th>\n<th>Example</th>\n<th>Ruling</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>Declaration parameter inference</strong></td>\n<td><code>function f(x = 1) {}</code></td>\n<td>not supported, public declaration surfaces need explicit parameter types</td>\n</tr>\n<tr>\n<td><strong>Bodyless concrete overloads</strong></td>\n<td><code>function f(x: string);</code></td>\n<td>not supported outside declaration contexts, just write multiple bodies</td>\n</tr>\n</tbody></table></div><h3 id=\"variance\">Variance</h3><p>TypeScript&#39;s best known soundness hole is closed: mutable positions are invariant.</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Feature</th>\n<th>Example</th>\n<th>Ruling</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>Mutable covariance</strong></td>\n<td><code>Circle[]</code> as <code>Shape[]</code></td>\n<td>not supported, mutable generic positions are invariant</td>\n</tr>\n</tbody></table></div><h4 id=\"arrays\">Arrays</h4><p>Readonly views keep the safe half of array covariance:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Arrays</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">class</span> <span data-k=\"type\">Shape</span> <span data-k=\"punct\">{</span><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">class</span> <span data-k=\"type\">Circle</span> <span data-k=\"keyword\">extends</span> <span data-k=\"type\">Shape</span> <span data-k=\"punct\">{</span><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">const</span> <span data-k=\"name\">circles</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Circle</span><span data-k=\"punct\">[</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">shapes</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Shape</span><span data-k=\"punct\">[</span><span data-k=\"punct\">]</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">circles</span><span data-k=\"punct\">;</span>        <span data-k=\"comment\">// ERROR: writing a Square through `shapes` would corrupt `circles`</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">view</span><span data-k=\"punct\">:</span> <span data-k=\"keyword\">readonly</span> <span data-k=\"type\">Shape</span><span data-k=\"punct\">[</span><span data-k=\"punct\">]</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">circles</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// OK: readonly views are covariant</span></span></span></code></pre></figure><h3 id=\"guards\">Guards</h3><p>Flow narrowing works as in TypeScript; only the guards themselves change.</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Feature</th>\n<th>Example</th>\n<th>Ruling</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>Truthiness</strong></td>\n<td><code>if (value)</code></td>\n<td>boolean values only, control flow needs explicit tests</td>\n</tr>\n<tr>\n<td><strong>Runtime <code>typeof</code> narrowing</strong></td>\n<td><code>typeof x === &quot;string&quot;</code></td>\n<td>not supported, use <code>is</code> or <code>instanceof</code></td>\n</tr>\n<tr>\n<td><strong>Type queries</strong></td>\n<td><code>typeof value</code></td>\n<td>supported in type position only</td>\n</tr>\n<tr>\n<td><strong>Type predicate / assertion signatures</strong></td>\n<td><code>value is T</code>, <code>asserts value is T</code></td>\n<td>not supported, callable type guards claim refinements that cannot be checked</td>\n</tr>\n</tbody></table></div><h4 id=\"truthiness\">Truthiness</h4><p><code>if</code> takes booleans, not values:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Truthiness</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">printAll</span><span data-k=\"punct\">(</span><span data-k=\"name\">values</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span> <span data-k=\"punct\">|</span> <span data-k=\"type\">string</span><span data-k=\"punct\">[</span><span data-k=\"punct\">]</span> <span data-k=\"punct\">|</span> <span data-k=\"literal\">null</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">void</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">if</span> <span data-k=\"punct\">(</span><span data-k=\"name\">values</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">        <span data-k=\"comment\">// ERROR: condition must be boolean</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">    <span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">if</span> <span data-k=\"punct\">(</span><span data-k=\"name\">values</span> <span data-k=\"punct\">!==</span> <span data-k=\"literal\">null</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\">        <span data-k=\"comment\">// OK: same narrowing, explicit test</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\">    <span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><h4 id=\"is\">Is</h4><p><code>is</code> replaces both runtime <code>typeof</code> tests and predicate signatures, and the compiler checks it instead of trusting it:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Is</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">padLeft</span><span data-k=\"punct\">(</span><span data-k=\"name\">padding</span><span data-k=\"punct\">:</span> <span data-k=\"type\">number</span> <span data-k=\"punct\">|</span> <span data-k=\"type\">string</span><span data-k=\"punct\">,</span> <span data-k=\"name\">input</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">if</span> <span data-k=\"punct\">(</span><span data-k=\"name\">padding</span> is <span data-k=\"name\">number</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">        <span data-k=\"keyword\">return</span> <span data-k=\"string\">&quot; &quot;</span><span data-k=\"punct\">.</span><span data-k=\"property\">repeat</span><span data-k=\"punct\">(</span><span data-k=\"name\">padding</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">+</span> <span data-k=\"name\">input</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">    <span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">return</span> <span data-k=\"name\">padding</span> <span data-k=\"punct\">+</span> <span data-k=\"name\">input</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><h3 id=\"operators\">Operators</h3><p>Operators keep their JavaScript meaning wherever JavaScript has one, and stop existing where it does not.</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Feature</th>\n<th>Example</th>\n<th>Ruling</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>Loose equality coercion</strong></td>\n<td><code>a == b</code> on objects</td>\n<td>no object coercion</td>\n</tr>\n<tr>\n<td><strong><code>===</code> on value types</strong></td>\n<td><code>pointA === pointB</code></td>\n<td>rejected for structs, tuples, and fixed arrays, use <code>Equal</code></td>\n</tr>\n<tr>\n<td><strong>Coercion hooks</strong></td>\n<td><code>valueOf</code>, <code>Symbol.toPrimitive</code></td>\n<td>not used for implicit coercion</td>\n</tr>\n<tr>\n<td><strong>Symbol magic</strong></td>\n<td><code>Symbol.hasInstance</code>, <code>Symbol.species</code></td>\n<td>not supported, use typed protocols</td>\n</tr>\n<tr>\n<td><strong>Non-null assertions</strong></td>\n<td><code>value!</code></td>\n<td>supported as <code>Try</code> / must unwrapping, an explicit runtime operation</td>\n</tr>\n<tr>\n<td><strong>Type angle assertions</strong></td>\n<td><code>&lt;T&gt;value</code></td>\n<td>not supported, use <code>value as T</code> or <code>value satisfies T</code></td>\n</tr>\n</tbody></table></div><h4 id=\"equality\">Equality</h4><p>Value types compare with <code>Equal</code>, not identity:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Equality</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">struct</span> <span data-k=\"type\">Point</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"property\">x</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"property\">y</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"type\">Point</span> <span data-k=\"punct\">{</span> <span data-k=\"property\">x</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">1</span><span data-k=\"punct\">,</span> <span data-k=\"property\">y</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">2</span> <span data-k=\"punct\">}</span> <span data-k=\"punct\">===</span> <span data-k=\"type\">Point</span> <span data-k=\"punct\">{</span> <span data-k=\"property\">x</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">1</span><span data-k=\"punct\">,</span> <span data-k=\"property\">y</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">2</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// ERROR: `===` has no JS meaning for value types</span></span></span></code></pre></figure><h3 id=\"closures\">Closures</h3><p>Callable context is explicit: no ambient <code>arguments</code>, no dynamic <code>this</code> rebinding.</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Feature</th>\n<th>Example</th>\n<th>Ruling</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>Ambient call metadata</strong></td>\n<td><code>arguments</code>, <code>new.target</code>, dynamic <code>this</code></td>\n<td>not supported as magic bindings, callable context is explicit</td>\n</tr>\n<tr>\n<td><strong>Ambiguous generic arrow</strong></td>\n<td><code>&lt;T&gt;() =&gt; value</code></td>\n<td>not supported, ambiguous with TSX, use <code>&lt;T,&gt;() =&gt; value</code></td>\n</tr>\n<tr>\n<td><strong>Dynamic constructors</strong></td>\n<td><code>new (factory())()</code></td>\n<td>not supported, construct values with type syntax like <code>new Widget&lt;T&gt;()</code></td>\n</tr>\n</tbody></table></div><h3 id=\"loops\">Loops</h3><p>Every loop form works unchanged; only the manual iteration protocol is replaced.\n(e.g., <code>switch</code> still has TypeScript fallthrough semantics)</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Feature</th>\n<th>Example</th>\n<th>Ruling</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>Manual iterator protocol</strong></td>\n<td><code>iter.next().done</code></td>\n<td>not supported, iteration is the nominal <code>Iterator</code> protocol, while <code>for-of</code> and spread lower unchanged</td>\n</tr>\n<tr>\n<td><strong>Destructuring in <code>for-of</code></strong></td>\n<td><code>for (const { name } of users)</code></td>\n<td>supported</td>\n</tr>\n<tr>\n<td><strong><code>for-in</code></strong></td>\n<td><code>for (const key in object)</code></td>\n<td>supported for object-shaped receivers and yields <code>string</code> keys</td>\n</tr>\n</tbody></table></div><h3 id=\"trees\">Trees</h3><p>TSX works as tree syntax, minus XML namespace semantics.</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Feature</th>\n<th>Example</th>\n<th>Ruling</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>XML namespace resolution</strong></td>\n<td><code>&lt;svg:path /&gt;</code></td>\n<td>no <code>xmlns</code> binding semantics, namespaced tags are intrinsic string tag names</td>\n</tr>\n</tbody></table></div><h3 id=\"errors\">Errors</h3><p>Failures are <code>Result</code> values: <code>throw</code> is gone, and a <code>Promise</code> never rejects.</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Feature</th>\n<th>Example</th>\n<th>Ruling</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>Exceptions</strong></td>\n<td>executing <code>throw</code></td>\n<td>not supported in native Destack code</td>\n</tr>\n<tr>\n<td><strong><code>try</code> / <code>catch</code> / <code>finally</code></strong></td>\n<td><code>try { ... } catch (e) { ... }</code></td>\n<td>works, as sugar over <code>Result</code> control flow</td>\n</tr>\n<tr>\n<td><strong>Catch destructuring</strong></td>\n<td><code>catch ({ message })</code></td>\n<td>supported when the pattern is irrefutable for the failure value</td>\n</tr>\n<tr>\n<td><strong>Promise rejection</strong></td>\n<td><code>.catch</code>, <code>Promise.reject</code></td>\n<td>gone, a <code>Promise&lt;T&gt;</code> always fulfills</td>\n</tr>\n<tr>\n<td><strong>Rejection-shaped APIs</strong></td>\n<td><code>Promise.any</code>, <code>allSettled</code>, two-arg <code>then</code></td>\n<td>gone with rejection</td>\n</tr>\n<tr>\n<td><strong>Floating promises</strong></td>\n<td>bare <code>refresh();</code> statement</td>\n<td>denied by default, await it, return it, or hand it to a scope</td>\n</tr>\n<tr>\n<td><strong>Thenables</strong></td>\n<td><code>await customThenable</code></td>\n<td>not supported, <code>await</code> works on the well known <code>Promise&lt;T&gt;</code> only</td>\n</tr>\n</tbody></table></div><h4 id=\"exceptions\">Exceptions</h4><p>The consuming side still reads like TypeScript:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Exceptions</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">newtype</span> <span data-k=\"type\">ParseError</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">parsePort</span><span data-k=\"punct\">(</span><span data-k=\"name\">raw</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">uint16</span><span data-k=\"punct\">,</span> <span data-k=\"type\">ParseError</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">try</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">const</span> <span data-k=\"name\">port</span> <span data-k=\"punct\">=</span> <span data-k=\"function\">parsePort</span><span data-k=\"punct\">(</span><span data-k=\"name\">input</span><span data-k=\"punct\">)</span><span data-k=\"punct\">?</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\">    <span data-k=\"function\">connect</span><span data-k=\"punct\">(</span><span data-k=\"name\">port</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span> <span data-k=\"keyword\">catch</span> <span data-k=\"punct\">(</span><span data-k=\"message\">error: ParseError) {</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\">    <span data-k=\"function\">report</span><span data-k=\"punct\">(</span><span data-k=\"name\">error</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><h4 id=\"promises\">Promises</h4><p>Async failure travels as <code>AsyncResult&lt;T, E&gt;</code>, which is just <code>Promise&lt;Result&lt;T, E&gt;&gt;</code>:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Promises</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">load</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Promise</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"function\">load</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">.</span><span data-k=\"property\">catch</span><span data-k=\"punct\">(</span><span data-k=\"name\">report</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// ERROR: `catch` does not exist, promises do not reject</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">fetchUser</span><span data-k=\"punct\">(</span><span data-k=\"name\">id</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">AsyncResult</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"type\">LoadError</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">async</span> <span data-k=\"keyword\">function</span> <span data-k=\"function\">rename</span><span data-k=\"punct\">(</span><span data-k=\"name\">id</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">,</span> <span data-k=\"name\">name</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">AsyncResult</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"type\">LoadError</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">const</span> <span data-k=\"name\">user</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">(</span><span data-k=\"keyword\">await</span> <span data-k=\"function\">fetchUser</span><span data-k=\"punct\">(</span><span data-k=\"name\">id</span><span data-k=\"punct\">)</span><span data-k=\"punct\">)</span><span data-k=\"punct\">?</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">return</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">.</span><span data-k=\"property\">ok</span><span data-k=\"punct\">(</span><span data-k=\"name\">user</span><span data-k=\"punct\">.</span><span data-k=\"property\">with</span><span data-k=\"punct\">(</span><span data-k=\"punct\">{</span> name <span data-k=\"punct\">}</span><span data-k=\"punct\">)</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><h3 id=\"decorators\">Decorators</h3><p>Decorators stay, and move to compile time: a decorator is a <code>comptime</code> value that may transform its target as a <a href=\"/docs/language/expressions/#macros\">macro</a>.</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Feature</th>\n<th>Example</th>\n<th>Ruling</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>Class and member decorators</strong></td>\n<td><code>@route(&quot;/users&quot;) class ... </code></td>\n<td>supported, evaluated at compile time</td>\n</tr>\n<tr>\n<td><strong>Runtime decorator metadata</strong></td>\n<td><code>emitDecoratorMetadata</code></td>\n<td>not supported, use <a href=\"/docs/language/types/#reflection\">reflection</a></td>\n</tr>\n</tbody></table></div><h3 id=\"comptime\">Comptime</h3><p>Runtime code generation conflicts with ahead-of-time compilation, so generation moves to compile time.</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Feature</th>\n<th>Example</th>\n<th>Ruling</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>Dynamic code generation</strong></td>\n<td>runtime <code>eval</code>, <code>new Function</code></td>\n<td>not supported except explicit <code>comptime eval</code></td>\n</tr>\n</tbody></table></div><h2 id=\"rust\">Rust</h2><p>Destack&#39;s memory model is Rust-shaped with inverted defaults: values are managed unless you opt into ownership, and mutability is decoupled from exclusivity.</p>\n<h3 id=\"ownership\">Ownership</h3><h4 id=\"defaults\">Defaults</h4><p>In Rust every value has exactly one owner.\nIn Destack the same is true, but for managed values the owner is the runtime, and ownership in the Rust sense is opt-in with <code>^T</code>:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Defaults</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">user</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span> <span data-k=\"type\">User</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>         <span data-k=\"comment\">// managed: the runtime owns it</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">owned</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">^</span><span data-k=\"type\">User</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span> <span data-k=\"type\">User</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// owned: single owner, deterministic drop</span></span></span></code></pre></figure><p>The managed default is why existing TypeScript works unchanged.</p>\n<h4 id=\"borrowing\">Borrowing</h4><p>Unlike in Rust, mutability is decoupled from borrowing: there are three borrow forms, and the aliased mutable <code>&amp;T</code> sits between Rust&#39;s two.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Borrowing</span><span class=\"markdown-code__format\">.rust</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span class=\"hljs-keyword\">let</span> mut point = <span class=\"hljs-title class_\">Point</span> { <span class=\"hljs-attr\">x</span>: <span class=\"hljs-number\">1</span>, <span class=\"hljs-attr\">y</span>: <span class=\"hljs-number\">2</span> };</span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span class=\"hljs-keyword\">let</span> a = &amp;mut point;</span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span class=\"hljs-keyword\">let</span> b = &amp;mut point; <span class=\"hljs-comment\">// ERROR: cannot borrow `point` as mutable more than once</span></span></span></code></pre></figure><figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Borrowing</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">point</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">^</span><span data-k=\"type\">Point</span> <span data-k=\"punct\">{</span> <span data-k=\"property\">x</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">1</span><span data-k=\"punct\">,</span> <span data-k=\"property\">y</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">2</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">a</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"name\">point</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">b</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"name\">point</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// OK: mutable borrows may alias</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"name\">a</span><span data-k=\"punct\">.</span><span data-k=\"property\">x</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">3</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"name\">b</span><span data-k=\"punct\">.</span><span data-k=\"property\">y</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">4</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><p>This is sound because a Worker is a single-threaded execution domain with explicit suspension points, so the writes cannot race.\n<code>&amp;exclusive</code> is <code>&amp;mut</code>, and it still exists for when we do want no aliasing:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Borrowing</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code><span data-k=\"keyword\">let</span> <span data-k=\"name\">c</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span>exclusive <span data-k=\"name\">point</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// ERROR: `a` and `b` are still live</span></code></pre></figure><p>Interior mutability (<code>Cell</code>, <code>RefCell</code>) exists too, but aliased <code>&amp;T</code> covers most of what Rust needs it for.</p>\n<h4 id=\"exclusivity\">Exclusivity</h4><p>Exclusivity is reserved for operations that may invalidate another borrow, instead of being required for every write.\nWhere invalidation is possible, Destack and Rust agree:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Exclusivity</span><span class=\"markdown-code__format\">.rust</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span class=\"hljs-keyword\">let</span> mut items = vec![<span class=\"hljs-number\">1</span>, <span class=\"hljs-number\">2</span>, <span class=\"hljs-number\">3</span>];</span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span class=\"hljs-keyword\">let</span> first = &amp;items[<span class=\"hljs-number\">1</span>];</span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">items.<span class=\"hljs-title function_\">push</span>(<span class=\"hljs-number\">4</span>); <span class=\"hljs-comment\">// ERROR: cannot borrow `items` as mutable</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">first;</span></span></code></pre></figure><figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Exclusivity</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">items</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Array</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">int32</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">[</span><span data-k=\"literal\">1</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">2</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">3</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">item</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">readonly</span> <span data-k=\"name\">items</span><span data-k=\"punct\">[</span><span data-k=\"literal\">1</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"name\">items</span><span data-k=\"punct\">.</span><span data-k=\"property\">push</span><span data-k=\"punct\">(</span><span data-k=\"literal\">4</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// ERROR: growth needs exclusive access while `item` is live</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"name\">item</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><h4 id=\"moves\">Moves</h4><p>Owned values move exactly like Rust values; managed handles copy freely.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Moves</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">a</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">^</span><span data-k=\"type\">Buffer</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Buffer</span><span data-k=\"punct\">.</span><span data-k=\"property\">open</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">b</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">a</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"name\">a</span><span data-k=\"punct\">.</span><span data-k=\"property\">length</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// ERROR: `a` moved into `b`</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">x</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span> <span data-k=\"type\">User</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">y</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">x</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"name\">x</span><span data-k=\"punct\">.</span><span data-k=\"property\">name</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// OK: managed handles alias</span></span></span></code></pre></figure><h4 id=\"drop\">Drop</h4><p><code>Drop</code> exists with the same meaning: owned values run their finalizer deterministically when their lifetime ends, and managed values run it when the garbage collector reclaims them.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Drop</span><span class=\"markdown-code__format\">.rust</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\">impl <span class=\"hljs-title class_\">Drop</span> <span class=\"hljs-keyword\">for</span> <span class=\"hljs-title class_\">Connection</span> {</span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    fn <span class=\"hljs-title function_\">drop</span>(<span class=\"hljs-params\">&amp;mut self</span>) { self.<span class=\"hljs-title function_\">close</span>(); }</span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">}</span></span></code></pre></figure><figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Drop</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">class</span> <span data-k=\"type\">Connection</span> <span data-k=\"keyword\">implements</span> <span data-k=\"type\">Drop</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"property\">drop</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">void</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">        <span data-k=\"name\">this</span><span data-k=\"punct\">.</span><span data-k=\"property\">close</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">    <span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><h3 id=\"lifetimes\">Lifetimes</h3><h4 id=\"inference\">Inference</h4><p>Lifetimes are ordinary <code>comptime</code> value parameters (<code>&lt;comptime L: Lifetime&gt;</code> on <code>Borrowed&lt;T, L&gt;</code>), and they are inferred everywhere, including from function bodies.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Inference</span><span class=\"markdown-code__format\">.rust</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\">fn first&lt;<span class=\"hljs-string\">&#x27;a&gt;(items: &amp;&#x27;</span>a [String]) -&gt; &amp;<span class=\"hljs-string\">&#x27;a str {</span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    &amp;items[0]</span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">}</span></span></span></code></pre></figure><figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Inference</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">first</span><span data-k=\"punct\">(</span><span data-k=\"name\">items</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"punct\">[</span><span data-k=\"type\">string</span><span data-k=\"punct\">]</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">string</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"punct\">&amp;</span><span data-k=\"name\">items</span><span data-k=\"punct\">[</span><span data-k=\"literal\">0</span><span data-k=\"punct\">]</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><h4 id=\"structs\">Structs</h4><p>Borrow-holding structs work like Rust&#39;s, with the lifetime as a <code>comptime</code> parameter:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Structs</span><span class=\"markdown-code__format\">.rust</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\">struct View&lt;<span class=\"hljs-string\">&#x27;a&gt; {</span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    name: &amp;&#x27;</span>a str,</span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">}</span></span></code></pre></figure><figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Structs</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">struct</span> <span data-k=\"type\">View</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">comptime</span> <span data-k=\"type\">L</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Lifetime</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"property\">name</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Borrowed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">string</span><span data-k=\"punct\">,</span> <span data-k=\"type\">L</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><h4 id=\"declarations\">Declarations</h4><p>The one place lifetimes are spelled out is <code>declare</code> signatures, because there is no body to infer from.\nThey participate in regular type algebra, including unions:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Declarations</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">choose</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">comptime</span> <span data-k=\"type\">L1</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Lifetime</span><span data-k=\"punct\">,</span> <span data-k=\"keyword\">comptime</span> <span data-k=\"type\">L2</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Lifetime</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"name\">first</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Borrowed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">string</span><span data-k=\"punct\">,</span> <span data-k=\"type\">L1</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">,</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"name\">second</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Borrowed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">string</span><span data-k=\"punct\">,</span> <span data-k=\"type\">L2</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">,</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Borrowed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">string</span><span data-k=\"punct\">,</span> <span data-k=\"type\">L1</span> <span data-k=\"punct\">|</span> <span data-k=\"type\">L2</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><h3 id=\"traits\">Traits</h3><h4 id=\"interfaces\">Interfaces</h4><p>Traits map to <code>newtype interface</code>s.\nThe standard <code>Iterator</code> is deliberately the same shape:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Interfaces</span><span class=\"markdown-code__format\">.rust</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\">trait Iterator {</span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span class=\"hljs-built_in\">type</span> Item;</span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    fn next(&amp;mut self) -&gt; Option&lt;Self::Item&gt;;</span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">}</span></span></code></pre></figure><figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Interfaces</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">newtype</span> <span data-k=\"keyword\">interface</span> <span data-k=\"type\">Iterator</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">type</span> <span data-k=\"type\">Item</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">type</span> <span data-k=\"type\">Return</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">void</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">    <span data-k=\"property\">next</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">IteratorResult</span><span data-k=\"punct\">&lt;</span>this<span data-k=\"punct\">.</span><span data-k=\"type\">Item</span><span data-k=\"punct\">,</span> this<span data-k=\"punct\">.</span><span data-k=\"type\">Return</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><h4 id=\"implementations\">Implementations</h4><p>There is no orphan rule: any module may implement any interface for any type, because Destack compiles whole programs and checks uniqueness globally.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Implementations</span><span class=\"markdown-code__format\">.rust</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span class=\"hljs-comment\">// ERROR: only traits defined in the current crate can be implemented (E0117)</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">impl <span class=\"hljs-title class_\">Display</span> <span class=\"hljs-keyword\">for</span> <span class=\"hljs-title class_\">Vec</span>&lt;u8&gt; { ... }</span></span></code></pre></figure><figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Implementations</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// fine: `implements` is globally unique per (type, interface) pair</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">extension</span> <span data-k=\"keyword\">of</span> <span data-k=\"type\">Array</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">implements</span> <span data-k=\"type\">Show</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"property\">show</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">        <span data-k=\"string\">`${this.length} bytes`</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\">    <span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>Conflicts between packages are whole-program compile errors, and libraries should only implement pairs they own one side of (a default-<code>warn</code> diagnostic nudges accordingly).</p>\n<h4 id=\"blankets\">Blankets</h4><p>Blanket implementations are supported with one familiar restriction: an <code>implements</code> blanket over a bare bounded parameter may only come from the package that declares the interface.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Blankets</span><span class=\"markdown-code__format\">.rust</span></figcaption><pre tabindex=\"0\"><code>impl&lt;<span class=\"hljs-attr\">T</span>: <span class=\"hljs-title class_\">Display</span>&gt; <span class=\"hljs-title class_\">Pretty</span> <span class=\"hljs-keyword\">for</span> T { ... } <span class=\"hljs-comment\">// only valid in the crate that owns Pretty</span></code></pre></figure><figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Blankets</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code><span data-k=\"keyword\">extension</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Show</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">of</span> <span data-k=\"type\">T</span> <span data-k=\"keyword\">implements</span> <span data-k=\"type\">Pretty</span> <span data-k=\"punct\">{</span> <span data-k=\"punct\">..</span><span data-k=\"punct\">.</span> <span data-k=\"punct\">}</span> <span data-k=\"comment\">// same rule, same reason</span></code></pre></figure><p>Blankets over nominal applications (<code>extension&lt;T&gt; of Box&lt;T&gt; implements Show</code>) are open to anyone, which Rust&#39;s orphan rule forbids.</p>\n<h4 id=\"associated-types\">Associated Types</h4><p>Associated types and constants work as in Rust, with positional refinement as sugar:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Associated Types</span><span class=\"markdown-code__format\">.rust</span></figcaption><pre tabindex=\"0\"><code>fn sum(values: impl Iterator<span class=\"hljs-tag\">&lt;<span class=\"hljs-name\">Item</span> = <span class=\"hljs-string\">u8</span>&gt;</span>) -&gt; u32 { ... }</code></pre></figure><figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Associated Types</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code><span data-k=\"keyword\">function</span> <span data-k=\"function\">sum</span><span data-k=\"punct\">(</span><span data-k=\"name\">values</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Iterator</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">uint32</span> <span data-k=\"punct\">{</span> <span data-k=\"punct\">..</span><span data-k=\"punct\">.</span> <span data-k=\"punct\">}</span> <span data-k=\"comment\">// sugar for Iterator&lt;type Item = uint8&gt;</span></code></pre></figure><h3 id=\"data\">Data</h3><h4 id=\"enums-2\">Enums</h4><p>Rust enums map to <code>newtype</code> unions over object variants, with <code>@derive(Tagged)</code> supplying constructors and discriminants:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Enums</span><span class=\"markdown-code__format\">.rust</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span class=\"hljs-keyword\">enum</span> <span class=\"hljs-title class_\">Shape</span> {</span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span class=\"hljs-title class_\">Circle</span> { <span class=\"hljs-attr\">radius</span>: f64 },</span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span class=\"hljs-title class_\">Square</span> { <span class=\"hljs-attr\">side</span>: f64 },</span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">}</span></span></code></pre></figure><figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Enums</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\">@<span data-k=\"function\">derive</span><span data-k=\"punct\">(</span><span data-k=\"type\">Tagged</span><span data-k=\"punct\">)</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">newtype</span> <span data-k=\"type\">Shape</span> <span data-k=\"punct\">=</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"punct\">|</span> <span data-k=\"punct\">{</span> <span data-k=\"property\">kind</span><span data-k=\"punct\">:</span> <span data-k=\"string\">&quot;circle&quot;</span><span data-k=\"punct\">;</span> <span data-k=\"property\">radius</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float64</span> <span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">    <span data-k=\"punct\">|</span> <span data-k=\"punct\">{</span> <span data-k=\"property\">kind</span><span data-k=\"punct\">:</span> <span data-k=\"string\">&quot;square&quot;</span><span data-k=\"punct\">;</span> <span data-k=\"property\">side</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float64</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">match</span> <span data-k=\"punct\">(</span><span data-k=\"name\">shape</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\">    <span data-k=\"type\">Shape</span><span data-k=\"punct\">.</span><span data-k=\"property\">Circle</span><span data-k=\"punct\">(</span><span data-k=\"punct\">{</span> <span data-k=\"property\">radius</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"name\">radius</span> <span data-k=\"punct\">*</span> <span data-k=\"name\">radius</span> <span data-k=\"punct\">*</span> <span data-k=\"literal\">3.14</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\">    <span data-k=\"type\">Shape</span><span data-k=\"punct\">.</span><span data-k=\"property\">Square</span><span data-k=\"punct\">(</span><span data-k=\"punct\">{</span> <span data-k=\"property\">side</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"name\">side</span> <span data-k=\"punct\">*</span> <span data-k=\"name\">side</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><h4 id=\"optionality\">Optionality</h4><figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Optionality</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">some</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span> <span data-k=\"punct\">|</span> <span data-k=\"literal\">null</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">1</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">none</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span> <span data-k=\"punct\">|</span> <span data-k=\"literal\">null</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">null</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">type</span> <span data-k=\"type\">Present</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">NonNullable</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">int32</span> <span data-k=\"punct\">|</span> <span data-k=\"literal\">null</span> <span data-k=\"punct\">|</span> <span data-k=\"literal\">undefined</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><p>Destack does not mirror Rust&#39;s <code>Option&lt;T&gt;</code> as a standard carrier.\nOrdinary absence uses TypeScript-style <code>null</code> / <code>undefined</code> unions directly, while APIs that need to distinguish completion from a yielded nullish value use explicit tagged results like <code>IteratorResult&lt;Y, R&gt;</code>.</p>\n<h3 id=\"errors-2\">Errors</h3><h4 id=\"results\">Results</h4><p><code>Result&lt;T, E&gt;</code> and <code>?</code> carry over directly, and <code>try</code> / <code>catch</code> is sugar over the same control flow:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Results</span><span class=\"markdown-code__format\">.rust</span></figcaption><pre tabindex=\"0\"><code><span class=\"hljs-built_in\">let</span> user = load_user(<span class=\"hljs-built_in\">id</span>)?;</code></pre></figure><figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Results</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code><span data-k=\"keyword\">const</span> <span data-k=\"name\">user</span> <span data-k=\"punct\">=</span> <span data-k=\"function\">loadUser</span><span data-k=\"punct\">(</span><span data-k=\"name\">id</span><span data-k=\"punct\">)</span><span data-k=\"punct\">?</span><span data-k=\"punct\">;</span></code></pre></figure><h4 id=\"panics\">Panics</h4><p>Panics take string messages only, and there is no <code>catch_unwind</code>: the Worker is the fault boundary, and the supervising parent observes the exit.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Panics</span><span class=\"markdown-code__format\">.rust</span></figcaption><pre tabindex=\"0\"><code><span class=\"hljs-keyword\">let</span> result = <span class=\"hljs-attr\">std</span>::<span class=\"hljs-attr\">panic</span>::<span class=\"hljs-title function_\">catch_unwind</span>(|| <span class=\"hljs-title function_\">risky</span>()); <span class=\"hljs-comment\">// recoverable in-process</span></code></pre></figure><figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Panics</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code><span data-k=\"function\">panic</span><span data-k=\"punct\">(</span><span data-k=\"string\">&quot;invariant broken&quot;</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// unwinds the Worker; the parent sees WorkerExit &quot;panicked&quot;</span></code></pre></figure><h3 id=\"concurrency\">Concurrency</h3><h4 id=\"send-and-sync\">Send and Sync</h4><p><code>Send</code> and <code>Sync</code> exist with the same meaning and the same structural derivation, applied per memory form:</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Form</th>\n<th>Crosses Workers when</th>\n</tr>\n</thead><tbody><tr>\n<td>local managed <code>T</code></td>\n<td>never</td>\n</tr>\n<tr>\n<td><code>^T</code></td>\n<td><code>T: Send</code></td>\n</tr>\n<tr>\n<td><code>&amp;readonly T</code></td>\n<td><code>T: Sync</code>, owned or static source</td>\n</tr>\n<tr>\n<td><code>&amp;exclusive T</code></td>\n<td><code>T: Send</code>, owned or static source</td>\n</tr>\n<tr>\n<td><code>&amp;T</code></td>\n<td>never</td>\n</tr>\n</tbody></table></div><p>The <code>&amp;T</code> row is the cost of aliased mutability: it is only sound within one Worker, so it never crosses.</p>\n<h4 id=\"tasks\">Tasks</h4><p>Where <code>tokio::spawn</code> hands back a detachable <code>JoinHandle</code>, spawned work here is owned by a scope that cannot exit while children are pending:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Tasks</span><span class=\"markdown-code__format\">.rust</span></figcaption><pre tabindex=\"0\"><code><span class=\"hljs-keyword\">let</span> handle = <span class=\"hljs-attr\">tokio</span>::<span class=\"hljs-title function_\">spawn</span>(<span class=\"hljs-keyword\">async</span> { <span class=\"hljs-title function_\">fetch</span>().<span class=\"hljs-property\">await</span> }); <span class=\"hljs-comment\">// leaks if never awaited</span></code></pre></figure><figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Tasks</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">await</span> <span data-k=\"keyword\">using</span> <span data-k=\"name\">scope</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">TaskScope</span><span data-k=\"punct\">.</span><span data-k=\"property\">open</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">task</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">scope</span><span data-k=\"punct\">.</span><span data-k=\"property\">spawn</span><span data-k=\"punct\">(</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"function\">fetch</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// owned: cancelled or joined before the scope exits</span></span></span></code></pre></figure><h4 id=\"workers\">Workers</h4><p>Threads map to Workers: isolated heaps, explicit <code>shared</code> memory, and message passing.\nBorrows of owned data may cross into scoped child tasks (subject to <code>Send</code>), which gives fork-join parallelism over borrowed data without <code>Arc</code> ceremony.</p>\n<h3 id=\"generics-2\">Generics</h3><h4 id=\"monomorphization\">Monomorphization</h4><p>Both languages monomorphize explicit generics, and Destack uses <code>Dynamic&lt;T&gt;</code> for bare erased constraints, while explicit generic parameters preserve Rust-like zero-cost specialization:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Monomorphization</span><span class=\"markdown-code__format\">.rust</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\">fn <span class=\"hljs-title function_\">draw</span>(<span class=\"hljs-params\">shape: impl Shape</span>) { ... }     <span class=\"hljs-comment\">// argument position: universal</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">fn <span class=\"hljs-title function_\">make</span>() -&gt; impl <span class=\"hljs-title class_\">Shape</span> { ... }        <span class=\"hljs-comment\">// return position: existential</span></span></span></code></pre></figure><figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Monomorphization</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">draw</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Shape</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span><span data-k=\"name\">shape</span><span data-k=\"punct\">:</span> <span data-k=\"type\">T</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">void</span> <span data-k=\"punct\">{</span><span data-k=\"punct\">}</span> <span data-k=\"comment\">// same universal</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">make</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Shape</span> <span data-k=\"punct\">{</span> <span data-k=\"punct\">..</span><span data-k=\"punct\">.</span> <span data-k=\"punct\">}</span>             <span data-k=\"comment\">// same existential return checking</span></span></span></code></pre></figure><h4 id=\"constants\">Constants</h4><p>Const generics map to <code>comptime</code> parameters, and value constraints are spelled as interval bounds or checked with <code>comptime assert</code> at instantiation.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Constants</span><span class=\"markdown-code__format\">.rust</span></figcaption><pre tabindex=\"0\"><code>struct <span class=\"hljs-title class_\">Buffer</span>&lt;<span class=\"hljs-keyword\">const</span> <span class=\"hljs-attr\">N</span>: usize&gt; { <span class=\"hljs-attr\">data</span>: [u8; N] }</code></pre></figure><figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Constants</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">struct</span> <span data-k=\"type\">Buffer</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">comptime</span> <span data-k=\"type\">N</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">0</span><span data-k=\"punct\">..=</span><span data-k=\"literal\">4096</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"property\">data</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">;</span> <span data-k=\"type\">N</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><h4 id=\"erasure\">Erasure</h4><p><code>dyn Trait</code> maps to <code>Dynamic&lt;T&gt;</code>, with <code>DynamicSafe</code> mirroring object safety:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Erasure</span><span class=\"markdown-code__format\">.rust</span></figcaption><pre tabindex=\"0\"><code><span class=\"hljs-built_in\">let</span> shapes: Vec&lt;Box&lt;dyn Shape&gt;&gt; = vec![circle, square];</code></pre></figure><figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Erasure</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code><span data-k=\"keyword\">let</span> <span data-k=\"name\">shapes</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Dynamic</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Shape</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">[</span><span data-k=\"punct\">]</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">[</span><span data-k=\"name\">circle</span><span data-k=\"punct\">,</span> <span data-k=\"name\">square</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span></code></pre></figure><h4 id=\"variance-2\">Variance</h4><p>Rust infers variance and never surfaces it, while Destack computes it the same way but lets declarations pin it with <code>in</code> / <code>out</code>, checked against usage like TypeScript.</p>\n<h3 id=\"unsafe\">Unsafe</h3><p><code>@unsafe</code> plays the same role as <code>unsafe</code>, with the same culture: raw pointers are safe to create and carry, and only dereferencing them needs the marker.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Unsafe</span><span class=\"markdown-code__format\">.rust</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span class=\"hljs-keyword\">let</span> pointer = &amp;user <span class=\"hljs-keyword\">as</span> *<span class=\"hljs-keyword\">const</span> <span class=\"hljs-title class_\">User</span>;</span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">unsafe { (*pointer).<span class=\"hljs-property\">name</span>.<span class=\"hljs-title function_\">clone</span>() }</span></span></code></pre></figure><figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Unsafe</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">pointer</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">*</span><span data-k=\"type\">User</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"name\">user</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">@<span data-k=\"name\">unsafe</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">read</span><span data-k=\"punct\">(</span><span data-k=\"name\">pointer</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">*</span><span data-k=\"type\">User</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\">    <span data-k=\"name\">pointer</span><span data-k=\"punct\">.</span><span data-k=\"property\">name</span><span data-k=\"punct\">.</span><span data-k=\"property\">clone</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><h3 id=\"comptime-2\">Comptime</h3><h4 id=\"macros\">Macros</h4><p>Rust splits metaprogramming across <code>macro_rules!</code>, proc macros, and derive macros, each with its own toolchain.\nDestack has one mechanism: a decorator is a static term, and one that implements <code>Macro</code> may transform its target as a typed declaration using the well known <code>eval</code> function.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Macros</span><span class=\"markdown-code__format\">.rust</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span class=\"hljs-comment\">#[derive(Serialize)]</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">struct User { name: String }</span></span></code></pre></figure><figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Macros</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\">@<span data-k=\"function\">derive</span><span data-k=\"punct\">(</span><span data-k=\"type\">Serialize</span><span data-k=\"punct\">)</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">struct</span> <span data-k=\"type\">User</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"property\">name</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>Generated code comes from <code>comptime eval</code> over reflected declarations, so macros compose with ordinary functions and expansion runs to a fixed point.\nIn this example the <code>derive</code> can usually even be emitted since Destack additionally supports auto-derive for builtin derive macros.</p>\n<h4 id=\"const-functions\">Const Functions</h4><p><code>const fn</code> maps to <code>comptime</code> evaluation of ordinary functions: anything the compiler can run is fair game, with a budget instead of a stability whitelist.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Const Functions</span><span class=\"markdown-code__format\">.rust</span></figcaption><pre tabindex=\"0\"><code><span class=\"hljs-keyword\">const</span> <span class=\"hljs-attr\">SIZE</span>: usize = <span class=\"hljs-title function_\">compute_size</span>(); <span class=\"hljs-comment\">// compute_size must be a const fn</span></code></pre></figure><figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Const Functions</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code><span data-k=\"keyword\">const</span> <span data-k=\"type\">SIZE</span><span data-k=\"punct\">:</span> <span data-k=\"type\">usize</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">comptime</span> <span data-k=\"function\">computeSize</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// any function, evaluated during compilation</span></code></pre></figure><h2 id=\"flow\">Flow</h2><p>Flow tried sound-by-default inside TypeScript-shaped syntax first, and Destack lands on many of the same answers.</p>\n<h3 id=\"objects\">Objects</h3><h4 id=\"exactness\">Exactness</h4><p>Flow made object types exact by default; Destack gets the same rejections through freshness and excess property checks:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Exactness</span><span class=\"markdown-code__format\">.flow</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span class=\"hljs-keyword\">function</span> <span class=\"hljs-title function_\">send</span>(<span class=\"hljs-params\">user: { name: string }</span>) {}</span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span class=\"hljs-title function_\">send</span>({ <span class=\"hljs-attr\">name</span>: <span class=\"hljs-string\">&quot;Ada&quot;</span>, <span class=\"hljs-attr\">admin</span>: <span class=\"hljs-literal\">true</span> }); <span class=\"hljs-comment\">// ERROR: `admin` is missing in object type</span></span></span></code></pre></figure><figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Exactness</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">send</span><span data-k=\"punct\">(</span><span data-k=\"name\">user</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">{</span> <span data-k=\"property\">name</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">void</span> <span data-k=\"punct\">{</span><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"function\">send</span><span data-k=\"punct\">(</span><span data-k=\"punct\">{</span> <span data-k=\"property\">name</span><span data-k=\"punct\">:</span> <span data-k=\"string\">&quot;Ada&quot;</span><span data-k=\"punct\">,</span> <span data-k=\"property\">admin</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">true</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// ERROR: excess property `admin`</span></span></span></code></pre></figure><h3 id=\"nominality-2\">Nominality</h3><h4 id=\"classes-2\">Classes</h4><p>Both Flow and Destack make classes nominal, against TypeScript&#39;s structural treatment:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Classes</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">class</span> <span data-k=\"type\">Left</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"property\">value</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">0</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">class</span> <span data-k=\"type\">Right</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\">    <span data-k=\"property\">value</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">0</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">value</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Left</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span> <span data-k=\"type\">Right</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// ERROR in Flow and Destack, OK in TypeScript</span></span></span></code></pre></figure><h4 id=\"opaque-types\">Opaque Types</h4><p>Flow&#39;s <code>opaque type</code> is the closest thing in the TS family to <code>newtype</code>, with one difference: Flow&#39;s opacity ends at the module boundary, while a <code>newtype</code> is nominal everywhere and constructed explicitly.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Opaque Types</span><span class=\"markdown-code__format\">.flow</span></figcaption><pre tabindex=\"0\"><code><span class=\"hljs-keyword\">export</span> opaque <span class=\"hljs-keyword\">type</span> <span class=\"hljs-variable constant_\">ID</span> = <span class=\"hljs-built_in\">string</span>; <span class=\"hljs-comment\">// transparent inside this file, opaque outside</span></code></pre></figure><figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Opaque Types</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code><span data-k=\"keyword\">export</span> <span data-k=\"keyword\">newtype</span> <span data-k=\"type\">Id</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// nominal everywhere, constructed as Id(&quot;...&quot;)</span></code></pre></figure><h3 id=\"variance-3\">Variance</h3><h4 id=\"sigils\">Sigils</h4><p>Flow annotates variance per property with <code>+</code> / <code>-</code>; Destack computes it from the member surface, and <code>in</code> / <code>out</code> exist only as checked assertions:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Sigils</span><span class=\"markdown-code__format\">.flow</span></figcaption><pre tabindex=\"0\"><code><span class=\"hljs-built_in\">type</span> Source&lt;+T&gt; = { +value: T };</code></pre></figure><figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Sigils</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">interface</span> <span data-k=\"type\">Source</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">readonly</span> <span data-k=\"property\">value</span><span data-k=\"punct\">:</span> <span data-k=\"type\">T</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// computes covariant on its own</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><h3 id=\"predicates\">Predicates</h3><h4 id=\"guards-2\">Guards</h4><p>Flow&#39;s <code>%checks</code> functions assert refinements; Destack&#39;s <code>is</code> expressions are guards the compiler understands directly:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Guards</span><span class=\"markdown-code__format\">.flow</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span class=\"hljs-keyword\">function</span> <span class=\"hljs-title function_\">isString</span>(<span class=\"hljs-params\">value: mixed</span>): boolean %checks {</span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span class=\"hljs-keyword\">return</span> <span class=\"hljs-keyword\">typeof</span> value === <span class=\"hljs-string\">&quot;string&quot;</span>;</span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">}</span></span></code></pre></figure><figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Guards</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">if</span> <span data-k=\"punct\">(</span><span data-k=\"name\">value</span> is <span data-k=\"name\">string</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"name\">value</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><h2 id=\"assemblyscript\">AssemblyScript</h2><p>AssemblyScript is the closest cousin: TypeScript syntax compiled ahead-of-time with explicit numeric types.\nIts gaps show what a TS-shaped native language cannot afford to give up.</p>\n<h3 id=\"numbers\">Numbers</h3><h4 id=\"naming\">Naming</h4><p>The numeric types correspond one-to-one, spelled out so they read as TypeScript:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Naming</span><span class=\"markdown-code__format\">.ts</span></figcaption><pre tabindex=\"0\"><code><span class=\"hljs-keyword\">function</span> <span class=\"hljs-title function_\">clamp</span>(<span class=\"hljs-params\"><span class=\"hljs-attr\">value</span>: i32, <span class=\"hljs-attr\">low</span>: i32, <span class=\"hljs-attr\">high</span>: i32</span>): i32 { ... }</code></pre></figure><figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Naming</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code><span data-k=\"keyword\">function</span> <span data-k=\"function\">clamp</span><span data-k=\"punct\">(</span><span data-k=\"name\">value</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">,</span> <span data-k=\"name\">low</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">,</span> <span data-k=\"name\">high</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span> <span data-k=\"punct\">{</span> <span data-k=\"punct\">..</span><span data-k=\"punct\">.</span> <span data-k=\"punct\">}</span></code></pre></figure><p><code>number</code> stays an alias for <code>float64</code>, so unannotated TypeScript keeps its meaning.</p>\n<h4 id=\"overflow\">Overflow</h4><p>AssemblyScript wraps silently, matching WASM; Destack traps on overflow in every build mode, and wrapping is explicit:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Overflow</span><span class=\"markdown-code__format\">.ts</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span class=\"hljs-keyword\">let</span> <span class=\"hljs-attr\">big</span>: i32 = <span class=\"hljs-number\">2147483647</span>;</span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">big + <span class=\"hljs-number\">1</span>; <span class=\"hljs-comment\">// -2147483648, silently</span></span></span></code></pre></figure><figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Overflow</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">big</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">2147483647</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"name\">big</span> <span data-k=\"punct\">+</span> <span data-k=\"literal\">1</span><span data-k=\"punct\">;</span>                 <span data-k=\"comment\">// traps: overflow</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"name\">big</span><span data-k=\"punct\">.</span><span data-k=\"property\">wrappingAdd</span><span data-k=\"punct\">(</span><span data-k=\"literal\">1</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>      <span data-k=\"comment\">// -2147483648, explicitly</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"type\">Wrapping</span><span data-k=\"punct\">(</span><span data-k=\"name\">big</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">+</span> <span data-k=\"literal\">1</span><span data-k=\"punct\">;</span>       <span data-k=\"comment\">// or wrap by type</span></span></span></code></pre></figure><h3 id=\"expressiveness\">Expressiveness</h3><h4 id=\"closures-2\">Closures</h4><p>Closures over mutable locals - the everyday TypeScript AssemblyScript cannot compile - work natively:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Closures</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">counter</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">(</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"type\">int32</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">let</span> <span data-k=\"name\">count</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">0</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">return</span> <span data-k=\"punct\">(</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\">        <span data-k=\"name\">count</span> <span data-k=\"punct\">+=</span> <span data-k=\"literal\">1</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\">        <span data-k=\"name\">count</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\">    <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><h4 id=\"unions\">Unions</h4><p>Union types, the other major gap, are first-class and reified:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Unions</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">describe</span><span data-k=\"punct\">(</span><span data-k=\"name\">value</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span> <span data-k=\"punct\">|</span> <span data-k=\"type\">string</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"name\">value</span> is <span data-k=\"name\">string</span> <span data-k=\"punct\">?</span> <span data-k=\"name\">value</span> <span data-k=\"punct\">:</span> <span data-k=\"string\">`#${value}`</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><h3 id=\"memory\">Memory</h3><h4 id=\"values-2\">Values</h4><p><code>@unmanaged</code> classes map to <code>struct</code>: value types are a declaration form, not an annotation on classes.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Values</span><span class=\"markdown-code__format\">.ts</span></figcaption><pre tabindex=\"0\"><code><span class=\"hljs-meta\">@unmanaged</span> <span class=\"hljs-keyword\">class</span> <span class=\"hljs-title class_\">Vec2</span> { <span class=\"hljs-attr\">x</span>: f32; <span class=\"hljs-attr\">y</span>: f32; }</code></pre></figure><figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Values</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">struct</span> <span data-k=\"type\">Vec2</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"property\">x</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float32</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"property\">y</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float32</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><h4 id=\"equality-2\">Equality</h4><p>AssemblyScript&#39;s <code>==</code> / <code>===</code> split confused users badly enough that they changed it.\nDestack keeps <code>===</code> only where JavaScript gives it a meaning (primitives and managed identity) and rejects it elsewhere, so the question never comes up for value types.</p>\n<h2 id=\"c\">C#</h2><p>C# is the other Hejlsberg language, and several of its core distinctions transfer almost verbatim.</p>\n<h3 id=\"values-3\">Values</h3><h4 id=\"structs-and-classes\">Structs and Classes</h4><p>The <code>struct</code> / <code>class</code> split means the same thing: values copied inline versus managed references.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Structs and Classes</span><span class=\"markdown-code__format\">.csharp</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\">struct <span class=\"hljs-title class_\">Point</span> { <span class=\"hljs-keyword\">public</span> double X, Y; }</span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span class=\"hljs-keyword\">class</span> <span class=\"hljs-title class_\">User</span> { <span class=\"hljs-keyword\">public</span> <span class=\"hljs-built_in\">string</span> <span class=\"hljs-title class_\">Name</span> = <span class=\"hljs-string\">&quot;&quot;</span>; }</span></span></code></pre></figure><figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Structs and Classes</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">struct</span> <span data-k=\"type\">Point</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"property\">x</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float64</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"property\">y</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float64</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">class</span> <span data-k=\"type\">User</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\">    <span data-k=\"property\">name</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span> <span data-k=\"punct\">=</span> <span data-k=\"string\">&quot;&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><h4 id=\"records\">Records</h4><p>Records map to structs for value semantics or newtypes for nominal wrappers, with equality via <code>@derive(Equal)</code> instead of being implicit:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Records</span><span class=\"markdown-code__format\">.csharp</span></figcaption><pre tabindex=\"0\"><code>record Point(double X, double Y);</code></pre></figure><figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Records</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\">@<span data-k=\"function\">derive</span><span data-k=\"punct\">(</span><span data-k=\"type\">Equal</span><span data-k=\"punct\">)</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">struct</span> <span data-k=\"type\">Point</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"property\">x</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float64</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">    <span data-k=\"property\">y</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float64</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>(Though again it should be noted that Destack suports auto-deriving for builtin derives, so equality would be derived automatically here.)</p>\n<h4 id=\"properties\">Properties</h4><p>C# properties map to accessors directly:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Properties</span><span class=\"markdown-code__format\">.csharp</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span class=\"hljs-keyword\">class</span> <span class=\"hljs-title class_\">Counter</span> {</span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span class=\"hljs-keyword\">private</span> int value;</span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span class=\"hljs-keyword\">public</span> int <span class=\"hljs-title class_\">Count</span> {</span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">        <span class=\"hljs-function\"><span class=\"hljs-params\">get</span> =&gt;</span> value;</span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\">        <span class=\"hljs-function\"><span class=\"hljs-params\">set</span> =&gt;</span> <span class=\"hljs-variable language_\">this</span>.<span class=\"hljs-property\">value</span> = value;</span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\">    }</span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\">}</span></span></code></pre></figure><figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Properties</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">class</span> <span data-k=\"type\">Counter</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">private</span> <span data-k=\"property\">value</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">0</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">get</span> <span data-k=\"property\">count</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\">        <span data-k=\"name\">this</span><span data-k=\"punct\">.</span><span data-k=\"property\">value</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\">    <span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">set</span> <span data-k=\"property\">count</span><span data-k=\"punct\">(</span><span data-k=\"name\">next</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\">        <span data-k=\"name\">this</span><span data-k=\"punct\">.</span><span data-k=\"property\">value</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">next</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\">    <span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><h3 id=\"generics-3\">Generics</h3><h4 id=\"variance-4\">Variance</h4><p>The <code>in</code> / <code>out</code> spelling is C#&#39;s, with one difference: variance is computed from usage, and the annotations are checked assertions instead of requirements.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Variance</span><span class=\"markdown-code__format\">.csharp</span></figcaption><pre tabindex=\"0\"><code><span class=\"hljs-keyword\">interface</span> <span class=\"hljs-title class_\">ISource</span>&lt;out T&gt; { T <span class=\"hljs-title class_\">Take</span>(); }</code></pre></figure><figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Variance</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">interface</span> <span data-k=\"type\">Source</span><span data-k=\"punct\">&lt;</span>out <span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"property\">take</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">T</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><h4 id=\"constraints\">Constraints</h4><p><code>where</code> clauses are nearly character-identical:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Constraints</span><span class=\"markdown-code__format\">.csharp</span></figcaption><pre tabindex=\"0\"><code>T Largest<span class=\"hljs-tag\">&lt;<span class=\"hljs-name\">T</span>&gt;</span>(List<span class=\"hljs-tag\">&lt;<span class=\"hljs-name\">T</span>&gt;</span> values) where T : IComparable<span class=\"hljs-tag\">&lt;<span class=\"hljs-name\">T</span>&gt;</span> { ... }</code></pre></figure><figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Constraints</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code><span data-k=\"keyword\">function</span> <span data-k=\"function\">largest</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span><span data-k=\"name\">values</span><span data-k=\"punct\">:</span> <span data-k=\"type\">T</span><span data-k=\"punct\">[</span><span data-k=\"punct\">]</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">T</span> <span data-k=\"keyword\">where</span> <span data-k=\"type\">T</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Comparable</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span> <span data-k=\"punct\">..</span><span data-k=\"punct\">.</span> <span data-k=\"punct\">}</span></code></pre></figure><h3 id=\"errors-3\">Errors</h3><h4 id=\"exceptions-2\">Exceptions</h4><p>C# keeps exceptions; Destack moves failure into values like Rust:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Exceptions</span><span class=\"markdown-code__format\">.csharp</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span class=\"hljs-keyword\">try</span> {</span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span class=\"hljs-keyword\">var</span> user = <span class=\"hljs-keyword\">await</span> <span class=\"hljs-title class_\">LoadUser</span>(id);</span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">} <span class=\"hljs-keyword\">catch</span> (<span class=\"hljs-title class_\">LoadException</span> error) {</span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">    <span class=\"hljs-title class_\">Report</span>(error);</span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\">}</span></span></code></pre></figure><figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Exceptions</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">result</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">await</span> <span data-k=\"function\">loadUser</span><span data-k=\"punct\">(</span><span data-k=\"name\">id</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">match</span> <span data-k=\"punct\">(</span><span data-k=\"name\">result</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">    <span data-k=\"type\">Ok</span> <span data-k=\"punct\">{</span> <span data-k=\"property\">value</span> <span data-k=\"punct\">}</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"function\">use</span><span data-k=\"punct\">(</span><span data-k=\"name\">value</span><span data-k=\"punct\">)</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\">    <span data-k=\"type\">Err</span> <span data-k=\"punct\">{</span> <span data-k=\"property\">error</span> <span data-k=\"punct\">}</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"function\">report</span><span data-k=\"punct\">(</span><span data-k=\"name\">error</span><span data-k=\"punct\">)</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><h4 id=\"nullability\">Nullability</h4><p>C#&#39;s nullable reference types map to plain nullable unions, checked the same way:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Nullability</span><span class=\"markdown-code__format\">.csharp</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span class=\"hljs-built_in\">string</span>? name = <span class=\"hljs-title class_\">FindName</span>(id);</span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span class=\"hljs-keyword\">if</span> (name is not <span class=\"hljs-literal\">null</span>) { <span class=\"hljs-title class_\">Use</span>(name); }</span></span></code></pre></figure><figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Nullability</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">name</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span> <span data-k=\"punct\">|</span> <span data-k=\"literal\">null</span> <span data-k=\"punct\">=</span> <span data-k=\"function\">findName</span><span data-k=\"punct\">(</span><span data-k=\"name\">id</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">if</span> <span data-k=\"punct\">(</span><span data-k=\"name\">name</span> <span data-k=\"punct\">!==</span> <span data-k=\"literal\">null</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">    <span data-k=\"function\">use</span><span data-k=\"punct\">(</span><span data-k=\"name\">name</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><h3 id=\"concurrency-2\">Concurrency</h3><h4 id=\"async\">Async</h4><p><code>async</code> / <code>await</code> carries over unchanged, with one naming collision to know about: C#&#39;s <code>Task&lt;T&gt;</code> is Destack&#39;s <code>Promise&lt;T&gt;</code> (the awaitable value), while Destack&#39;s <code>Task&lt;T&gt;</code> is a scope-owned work item closer to a structured <code>Task.Run</code>.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Async</span><span class=\"markdown-code__format\">.csharp</span></figcaption><pre tabindex=\"0\"><code><span class=\"hljs-keyword\">async</span> <span class=\"hljs-title class_\">Task</span>&lt;<span class=\"hljs-title class_\">User</span>&gt; <span class=\"hljs-title class_\">LoadUser</span>(<span class=\"hljs-built_in\">string</span> id) { ... }</code></pre></figure><figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Async</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code><span data-k=\"keyword\">async</span> <span data-k=\"keyword\">function</span> <span data-k=\"function\">loadUser</span><span data-k=\"punct\">(</span><span data-k=\"name\">id</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Promise</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span> <span data-k=\"punct\">..</span><span data-k=\"punct\">.</span> <span data-k=\"punct\">}</span></code></pre></figure>", {  }),
} satisfies DocumentContent;

export default content;

/// Replace build-time asset placeholders with bundled URLs.
function resolveAssets(html: string, assets: Record<string, string>) {
    let resolved = html;

    for (const [placeholder, asset] of Object.entries(assets)) {
        resolved = resolved.replaceAll(placeholder, asset);
    }

    return resolved;
}
